mapper.select:
SELECT (SELECT count(1) FROM b_user bu, (SELECT bur.user_id FROM b_user bur, r_user_tenant rut WHERE bur.flag = 1 AND rut.flag = 1 AND bur.user_id = rut.user_id AND rut.tenant_id = #{tenantId}
AND rut.organization_id = #{orgId}
) tmp WHERE bu.flag = 1 AND bu.recommend_user_id = tmp.user_id AND bu.create_time BETWEEN #{startTime} AND #{endTime}) AS recommendCount, (SELECT COUNT(1) FROM b_user bu, r_user_tenant rut WHERE bu.flag = 1 AND rut.flag = 1 AND bu.user_id = rut.user_id AND bu.tenant_id = #{tenantId}
AND rut.organization_id = #{orgId}
AND rut.create_time BETWEEN #{startTime} AND #{endTime}) AS newCount, (SELECT COUNT( 1 ) FROM b_user bu LEFT JOIN r_user_tenant rut ON rut.flag = 1 AND bu.user_id = rut.user_id WHERE bu.flag = 1 AND bu.tenant_id = 1
AND rut.organization_id = #{orgId}
) AS totalCount

SELECT (SELECT COUNT(wf.form_id)
        FROM wf_form wf
        WHERE wf.flag = 1
          AND wf.form_type_id = 1
          AND wf.tenant_id = #{tenantId}

            AND wf.current_org_id = #{orgId}

          AND wf.create_time BETWEEN #{startTime} AND #{endTime}) AS newCount,
       (SELECT COUNT(wf.form_id)
        FROM wf_form wf
        WHERE wf.flag = 1
          AND wf.form_type_id = 1
          AND wf.tenant_id = #{tenantId}

            AND wf.current_org_id = #{orgId}

        ) AS totalCount

SELECT IFNULL(t1.totalCount, 0) AS totalCount, IFNULL(t1.totalAmount, 0) AS totalAmount, IFNULL(t2.newCount, 0) AS newCount, IFNULL(t2.newAmount, 0) AS newAmount FROM ( SELECT COUNT(sc.service_contract_id) AS totalCount, SUM(sc.amount) AS totalAmount FROM wf_form wf, sc_service_contract sc WHERE wf.flag = 1 AND sc.flag = 1 AND wf.form_id = sc.form_id AND wf.form_type_id = 1 AND wf.tenant_id = #{tenantId}
AND wf.current_org_id = #{orgId}
) t1, ( SELECT COUNT(sc.service_contract_id) AS newCount, SUM(sc.amount) AS newAmount FROM wf_form wf, sc_service_contract sc WHERE wf.flag = 1 AND sc.flag = 1 AND wf.form_id = sc.form_id AND wf.form_type_id = 1 AND wf.tenant_id = #{tenantId}
AND wf.current_org_id = #{orgId}
AND sc.signing_time BETWEEN #{startTime} AND #{endTime} ) t2

SELECT (SELECT COUNT(wc.complain_id)
        FROM w_complain wc,
             wf_form wf,
             r_form_consult_complain rfcc
        WHERE wc.flag = 1
          AND wf.flag = 1
          AND wc.complain_id = rfcc.complain_id
          AND wf.form_id = rfcc.consult_id
          AND wc.typef = 1
          AND wc.tenant_id = #{tenantId}

            AND wc.organization_id = #{orgId}

          AND wc.create_time BETWEEN #{startTime} AND #{endTime}
       ) AS newOrderCount,
       (SELECT COUNT(wc.complain_id)
        FROM w_complain wc,
             sc_service_contract ssc,
             r_form_consult_complain rfcc
        WHERE wc.flag = 1
          AND ssc.flag = 1
          AND wc.complain_id = rfcc.complain_id
          AND ssc.service_contract_id = rfcc.consult_id
          AND wc.typef = 2
          AND wc.tenant_id = #{tenantId}

            AND wc.organization_id = #{orgId}

          AND wc.create_time BETWEEN #{startTime} AND #{endTime}
        )    newContractCount

choose.when:
with tm as (
select '新用户增长曲线' as stat_desc, 'month' as stat_dim, '新增客户数' as stat_name, '个' as stat_unit, #{statDim} as item_name from dual union all select '新用户增长曲线' as stat_desc, 'month' as stat_dim, '推广客户数' as stat_name, '个' as stat_unit, #{statDim} as item_name from dual
) select tm.stat_desc, tm.stat_dim, tm.stat_name, tm.stat_unit, tm.item_name, ifnull(ts.item_val, 0) as item_val from tm left join ( ( select '新增客户数' as stat_name , date_format(bu.create_time, '%Y%m') as item_name , count(distinct bu.user_id) as item_val from b_user bu left join r_user_tenant rut on rut.flag = 1 and rut.user_id = bu.user_id where bu.flag = 1 and bu.create_time is not null and bu.tenant_id = #{tenantId} and bu.create_time between #{startTime} and #{endTime}
AND rut.organization_id = #{orgId}
group by date_format(bu.create_time, '%Y%m') ) union all ( select '推广客户数' as stat_name , date_format(bu.create_time, '%Y%m') as item_name , count(distinct bu.user_id) as item_val from b_user bu left join r_user_tenant rut on rut.flag = 1 and rut.user_id = bu.recommend_user_id where bu.flag = 1 and bu.create_time is not null and bu.recommend_user_id is not null and bu.tenant_id = #{tenantId} and bu.create_time between #{startTime} and #{endTime}
AND rut.organization_id = #{orgId}
group by date_format(bu.create_time, '%Y%m') ) ) as ts on ts.stat_name = tm.stat_name and ts.item_name = tm.item_name order by tm.item_name, tm.stat_name

choose.otherwise:
with tm as (
select '新用户增长曲线' as stat_desc, 'week' as stat_dim, '新增客户数' as stat_name, '个' as stat_unit, #{statDim} as item_name from dual union all select '新用户增长曲线' as stat_desc, 'week' as stat_dim, '推广客户数' as stat_name, '个' as stat_unit, #{statDim} as item_name from dual
) select tm.stat_desc, tm.stat_dim, tm.stat_name, tm.stat_unit, tm.item_name, ifnull(ts.item_val, 0) as item_val from tm left join ( ( select '新增客户数' as stat_name , yearweek(bu.create_time, 1) as item_name , count(distinct bu.user_id) as item_val from b_user bu left join r_user_tenant rut on rut.flag = 1 and rut.user_id = bu.user_id where bu.flag = 1 and bu.create_time is not null and bu.tenant_id = #{tenantId} and bu.create_time between #{startTime} and #{endTime}
AND rut.organization_id = #{orgId}
group by yearweek(bu.create_time, 1) ) union all ( select '推广客户数' as stat_name , yearweek(bu.create_time, 1) as item_name , count(distinct bu.user_id) as item_val from b_user bu left join r_user_tenant rut on rut.flag = 1 and rut.user_id = bu.recommend_user_id where bu.flag = 1 and bu.create_time is not null and bu.recommend_user_id is not null and bu.tenant_id = #{tenantId} and bu.create_time between #{startTime} and #{endTime}
AND rut.organization_id = #{orgId}
group by yearweek(bu.create_time, 1) ) ) as ts on ts.stat_name = tm.stat_name and ts.item_name = tm.item_name order by tm.item_name, tm.stat_name

choose.when:
with tm as (

    select '工单合同数量变化' as stat_desc, 'month' as stat_dim, '工单' as stat_name, '单' as stat_unit, #{statDim} as item_name from dual
    union all
    select '工单合同数量变化' as stat_desc, 'month' as stat_dim, '合同' as stat_name, '个' as stat_unit, #{statDim} as item_name from dual

)
select tm.stat_desc, tm.stat_dim, tm.stat_name, tm.stat_unit, tm.item_name, ifnull(ts.item_val, 0) as item_val
from tm left join (
    (
        select '工单' as stat_name
            , date_format(form_create_time, '%Y%m') as item_name
            , count(distinct form_id) as item_val
        from () as voc
        where tenant_id = #{tenantId}
        and form_create_time between #{startTime} and #{endTime}

            AND current_org_id = #{orgId}

        group by date_format(form_create_time, '%Y%m')
    )
    union all
    (
        select '合同' as stat_name
            , date_format(contract_create_time, '%Y%m') as item_name
            , count(distinct service_contract_id) as item_val
        from () as voc
        where tenant_id = #{tenantId}
        and contract_create_time between #{startTime} and #{endTime}

            AND service_unit = #{orgId}

        group by date_format(contract_create_time, '%Y%m')
    )
) as ts on ts.stat_name = tm.stat_name and ts.item_name = tm.item_name
order by tm.item_name, tm.stat_name desc

choose.otherwise:
with tm as (

select '工单合同数量变化' as stat_desc, 'week' as stat_dim, '工单' as stat_name, '单' as stat_unit, #{statDim} as item_name from dual
union all
select '工单合同数量变化' as stat_desc, 'week' as stat_dim, '合同' as stat_name, '个' as stat_unit, #{statDim} as item_name from dual

)
select tm.stat_desc, tm.stat_dim, tm.stat_name, tm.stat_unit, tm.item_name, ifnull(ts.item_val, 0) as item_val
from tm left join (
    (
        select '工单' as stat_name
            , yearweek(form_create_time, 1) as item_name
            , count(distinct form_id) as item_val
        from () as voc
        where tenant_id = #{tenantId}
        and form_create_time between #{startTime} and #{endTime}

            AND current_org_id = #{orgId}

        group by yearweek(form_create_time, 1)
    )
    union all
    (
        select '合同' as stat_name
            , yearweek(contract_create_time, 1) as item_name
            , count(distinct service_contract_id) as item_val
        from () as voc
        where tenant_id = #{tenantId}
        and contract_create_time between #{startTime} and #{endTime}

            AND service_unit = #{orgId}

        group by yearweek(contract_create_time, 1)
    )
) as ts on ts.stat_name = tm.stat_name and ts.item_name = tm.item_name
order by tm.item_name, tm.stat_name desc

choose.when:
with tm as (

    select '合同金额变化（单位：万元）' as stat_desc, 'month' as stat_dim, '新增合同金额' as stat_name, '万元' as stat_unit, #{statDim} as item_name from dual
    union all
    select '合同金额变化（单位：万元）' as stat_desc, 'month' as stat_dim, '合同总金额' as stat_name, '万元' as stat_unit, #{statDim} as item_name from dual

)
select tm.stat_desc, tm.stat_dim, tm.stat_name, tm.stat_unit, tm.item_name, round(ifnull(ts.item_val, 0) / 10000, 2) as item_val
from tm left join (
    (
        select '新增合同金额' as stat_name
            , date_format(contract_create_time, '%Y%m') as item_name
            , sum(amount) as item_val
        from () as voc
        where tenant_id = #{tenantId}
        and contract_create_time between #{startTime} and #{endTime}

            AND service_unit = #{orgId}

        group by date_format(contract_create_time, '%Y%m')
    )
    union all
    (
        select tm.stat_name, tm.item_name, sum(item_val) over(order by tm.item_name asc) as item_val
        from (
            select '合同总金额' as stat_name
                , date_format(contract_create_time, '%Y%m') as item_name
                , sum(amount) as item_val
            from () as voc
            where tenant_id = #{tenantId}
            and contract_create_time between #{startTime} and #{endTime}

                AND service_unit = #{orgId}

            group by date_format(contract_create_time, '%Y%m')
        )as tr
        right join tm on tm.stat_name = tr.stat_name and tm.item_name = tr.item_name
        where tm.stat_name = '合同总金额'
        order by tm.item_name
    )
) as ts on ts.stat_name = tm.stat_name and ts.item_name = tm.item_name
order by tm.item_name, tm.stat_name desc

