mapper.sql:
select '合同' as stat_name, wc.complain_id, wc.subject, wc.create_time, ssc.service_unit as org_id, ssc.tenant_id
from w_complain wc
join r_form_consult_complain rfcc on rfcc.complain_id = wc.complain_id
join sc_service_contract ssc on ssc.flag = 1 and ssc.service_contract_id = rfcc.consult_id
where wc.flag = 1
and wc.typef = 1
and ssc.tenant_id = #{tenantId}
and ssc.create_time between #{startTime} and #{endTime}

    AND ssc.service_unit = #{orgId}

union all
select '工单' as stat_name, wc.complain_id, wc.subject, wc.create_time, wf.current_org_id as org_id, wf.tenant_id
from w_complain wc
join r_form_consult_complain rfcc on rfcc.complain_id = wc.complain_id
join wf_form wf on wf.flag = 1 and wf.form_id = rfcc.consult_id
where wc.flag = 1
and wc.typef = 2
and wf.tenant_id = #{tenantId}
and wc.create_time between #{startTime} and #{endTime}

    AND wf.current_org_id = #{orgId}

choose.when:
with tm as (
select '投诉类型数量变化' as stat_desc, 'month' as stat_dim, '工单' as stat_name, '件' as stat_unit, #{statDim} as item_name from dual union all select '投诉类型数量变化' as stat_desc, 'month' as stat_dim, '合同' as stat_name, '件' as stat_unit, #{statDim} as item_name from dual
) select tm.stat_desc, tm.stat_dim, tm.stat_name, tm.stat_unit, tm.item_name, ifnull(ts.item_val, 0) as item_val from tm left join ( select stat_name , date_format(create_time, '%Y%m') as item_name , count(distinct complain_id) as item_val from () as vc group by stat_name, date_format(create_time, '%Y%m') ) as ts on ts.stat_name = tm.stat_name and ts.item_name = tm.item_name order by tm.item_name, tm.stat_name desc

choose.otherwise:
with tm as (
select '投诉类型数量变化' as stat_desc, 'week' as stat_dim, '工单' as stat_name, '件' as stat_unit, #{statDim} as item_name from dual union all select '投诉类型数量变化' as stat_desc, 'week' as stat_dim, '合同' as stat_name, '件' as stat_unit, #{statDim} as item_name from dual
) select tm.stat_desc, tm.stat_dim, tm.stat_name, tm.stat_unit, tm.item_name, ifnull(ts.item_val, 0) as item_val from tm left join ( select stat_name , yearweek(create_time, 1) as item_name , count(distinct complain_id) as item_val from () as vc group by stat_name, yearweek(create_time, 1) ) as ts on ts.stat_name = tm.stat_name and ts.item_name = tm.item_name order by tm.item_name, tm.stat_name desc

mapper.select:
SELECT bu.realname as realname, bu.mobile as mobile, bo.NAME as org_name, CONCAT(SUBSTRING(bur.open_id, 1, LENGTH(bur.open_id)-5), 'xxxxx') as promote_user_open_id, bur.realname as promote_user_name, bur.mobile as promote_user_phone, bur.create_time as promote_user_create_time FROM b_user bu, b_organization bo, r_user_tenant rut, b_user bur WHERE bu.flag = 1 AND bo.flag = 1 AND rut.flag = 1 AND bur.flag = 1 AND bu.user_id = rut.user_id AND bo.organization_id = rut.organization_id AND bu.user_id = bur.recommend_user_id AND bo.tenant_id = 1
AND bo.organization_id = #{orgId}
ORDER BY bo.organization_id,bu.user_id, bur.create_time
